	SUBROUTINE GS(E,NM,NPPM,NPTS,NCP)
	INTEGER*2 E,I,NC,K,L,M,N,KM1,NM,NPPM,NCP,NPTS
	REAL*4 SY,SX,SXX,SXY,CE,B0
	DIMENSION B0(124)
C
	INTEGER*2 MHV,IDM
	REAL*4 XD
	COMMON/BAKER/MHV(360,2),IDM(3,2),XD
C
	CHARACTER*1 DEBUG
	INTEGER*2 IKM,IXY,IGS,ISP,ICSP,IGK
	COMMON/FOX/DEBUG,IKM,IXY,IGS,ISP,ICSP,IGK
C
	INTEGER*2 NS
	REAL*4 X,Y,YHAT,Z,B1,DEL
	COMMON/INDIA/X(124),Y(124),YHAT(124,2),Z(124,2),B1(124,2),
     *DEL(124,2),NS(2)
C
C      TYPE *,'  E,NPTS:',E,NPTS
	AA=0.5*FLOAT(NPPM)/60.
	DO 10 I=1,NM+3
      YHAT(I,E)=0.
      Z(I,E)=0.
   10 B1(I,E)=0.
C
C*** GS EXPECTS NPTS >= 3 FROM SUB XYSET
   20 NC=NCP              !NEW COORDINATE PAIRS
      K=0			!SEGEMENT COUNTER
      L=1			!INTERCEPT COUNTER
      M=1			!POINT COUNTER
      N=M+NC			!NUMBER OF POINTS USED TO FIT LINE
C*** A SEGMENT IS NORMALLY DEFINED BY A SET OF COORDINATE PAIRS
C*****GET SUMS AND CROSS PRODUCTS USING PREDETERMINED NUMBER OF
C*****COORDINATE PAIRS - NORMALLY THREE
   25 SX=0.0
      SY=0.0
      SXY=0.0
      SXX=0.0
      DO 30 J=M,N
      SX=SX+X(J)
      SY=SY+Y(J)
      SXY=SXY+X(J)*Y(J)
   30 SXX=SXX+X(J)*X(J)
C*****INCREMENT SEGMENT COUNTER AND COMPUTE B0 AND B1 COEFFICIENTS
C*****OF THE CURRENT LINE SEGMENT
      K=K+1
      KM1=K-1
      CE=FLOATI(N-M+1)
      B1(K,E)=(CE*SXY-SX*SY)/(CE*SXX-SX*SX)
      B0(K)=(SY-B1(K,E)*SX)/CE
      IF(K.EQ.1)GOTO 50
C*** IF THE SLOPE OF THE CURRENT SEGMENT EQUALS THE SLOPE OF THE LAST
C*** SEGMENT DO NOT INCREMENT SEGMENT COUNTER OR COMPUTE INTERCEPT
      IF(B1(K,E).NE.B1(KM1,E))GOTO 32
      K=KM1
      N=N+1
      GOTO 50
   32 L=L+1
C*** COMPUTE SEGMENT INTERCEPT COORDINATES (YHAT,Z)
      Z(L,E)=(B0(KM1)-B0(K))/(B1(K,E)-B1(KM1,E))
      YHAT(L,E)=B0(K)+B1(K,E)*Z(L,E)
      IF(Z(2,E).LT.X(1))GOTO 33
      IF(Z(L,E)-X(N))35,35,33
   33 IF(L.GT.2)GOTO 40
      M=M-1
      IF(M.GT.0) GOTO 34
      K=0
      M=2
      N=M+NC
      GOTO 25
   34 K=KM1
      L=L-1
      GOTO 25
   35 IF(L.LE.2)GOTO 50
      IF(Z(L,E).LE.Z(L-1,E).OR.Z(L,E).GE.X(N))GOTO 40
      GOTO 50
C*** LOST SEGMENT CONTINUITY, ADJUST SEGMENT COUNTER, AND COMPUTE
C*** COEFICIENTS TO MAINTAIN CONTINUITY
   40 K=KM1
      A=((X(N-1)+X(N))/2.0)-Z(L-1,E)
C*** A SHOULD ALWAYS BE > 0
      IF(A.GT.0.0)GOTO 45
	PRINT *,' A,K,L,M,N:',A,K,L,M
	PRINT *,' X(N-1),X(N),Z(L-1,E):',X(N-1),X(N),Z(L-1,E)
   45 B1(K,E)=(((Y(N-1)+Y(N))/2.0)-YHAT(L-1,E))/A
      B0(K)=YHAT(L-1,E)-B1(K,E)*Z(L-1,E)
      L=L-1
   50 M=N-1
      N=M+NC
      IF(N.LE.NPTS)GOTO 25
   52 CONTINUE
      IF(Z(2,E).GE.0.0)GOTO 60
      L=L-1
      DO 55I=1,L
      Z(I,E)=Z(I+1,E)
      YHAT(I,E)=YHAT(I+1,E)
      B1(I,E)=B1(I+1,E)
      B0(I)=B0(I+1)
   55 CONTINUE
      GOTO 62
   60 Z(1,E)=-3.0*AA
	YHAT(1,E)=B0(1)-3.0*AA*B1(1,E)
   62 IF(Z(L,E).GE.24.0)GOTO 70
	Z(L+1,E)=24.0+3.0*AA
	YHAT(L+1,E)=YHAT(L,E)+(24.0+3.0*AA-Z(L,E))*B1(L,E)
      L=L+1
   70 NS(E)=L
	IF(DEBUG.EQ.'Y'.AND.IGS.EQ.1)CALL WRITEDAT(NS(E),YHAT(1,E),Z(1,E))
	RETURN
      END
